│                   └── fabric
│                       └── emerald_sword
│                           └── EmeraldSwordMod.java
└── fabric-plugin.gradle
└── fabric-plugin.gradle
```

### Step 2: Create the mod files

#### 1. `build.gradle`
This file is used to compile the mod and package it for Fabric.

```gradle
plugins {
    id "io.github.adamratzmanstudio.fabric" version "0.2.0"
    id "java"
}

group "com.example.fabric.emerald_sword"
version "1.0-SNAPSHOT"

repositories {
    mavenCentral()
}

dependencies {
    implementation "net.fabricmc:fabric-api-all:0.42.0+1.21"
}

fabric {
    apiVersion "0.42.0"
    remapper "io.github.adamratzmanstudio:adventure-api:0.1.8"
}
```

#### 2. `fabric-plugin.gradle`
This file is used to configure the mod.

```gradle
plugins {
    id "io.github.adamratzmanstudio.fabric"
}

fabric {
    remapper "io.github.adamratzmanstudio:adventure-api:0.1.8"
}
```

#### 3. `src/main/java/com/example/fabric/emerald_sword/EmeraldSwordMod.java`
This is the main mod class.

```java
package com.example.fabric.emerald_sword;

import net.fabricmc.api.ModInitializer;
import net.minecraft.item.SwordItem;
import net.minecraft.item.Item;
import net.minecraft.util.Identifier;
import net.minecraft.util.registry.Registry;

public class EmeraldSwordMod implements ModInitializer {
    @Override
    public void init() {
        Registry.register(Registry.ITEM, new Identifier("emerald_sword_mod", "emerald_sword"), new CustomEmeraldSword());
    }
}

public class CustomEmeraldSword extends SwordItem {
    public CustomEmeraldSword() {
        super(Enchantments.DAMAGE_ALL, -1, -1, new Item.Settings().maxDamage(1000));
    }

    @Override
    public float getAttackDamage() {
        return 5.0f; // Custom damage for the Emerald Sword
    }
}
```

### Step 3: Create the custom damage calculation

#### 4. `src/main/java/com/example/fabric/emerald_sword/EmeraldDamageableEntity.java`
This class will handle the damage calculation for the Emerald Sword.

```java
package com.example.fabric.emerald_sword;

import net.minecraft.entity.Entity;
import net.minecraft.entity.EntityType;
import net.minecraft.entity.LivingEntity;
import net.minecraft.entity.player.PlayerEntity;
import net.minecraft.item.ItemStack;
import net.minecraft.world.World;

public class EmeraldDamageableEntity extends LivingEntity {
    public EmeraldDamageableEntity(EntityType<? extends LivingEntity> type, World world) {
        super(type, world);
    }

    @Override
    public boolean attack(LivingEntity target, float damage) {
        if (target instanceof PlayerEntity) {
            PlayerEntity player = (PlayerEntity) target;
            ItemStack stack = player.getMainHandItem();
            if (stack.getItem() instanceof CustomEmeraldSword) {
                ItemStack emeraldSword = stack;
                emeraldSword.damageItem(1, player, (playerEntity) -> {
                    playerEntity.sendToolEffect(emeraldSword, ToolEffect.Action.REMOVE);
                });
                player.getHealthComponent().damage(DamageSource.OUT_OF_WORLD, damage);
                return true;
            }
        }
        return super.attack(target, damage);
    }
}
```

### Step 4: Compile and Test

1. Open a terminal and navigate to the root directory of your mod.
2. Run the following command to compile the mod:

```bash
./gradlew build
```

3. Place the compiled jar file in your mods folder.

### Step 5: Load the mod in-game

1. Start Minecraft and load your world.
2. Load the mod by going to the mods tab and clicking on the mod you just compiled.

### Conclusion

You now have a complete Minecraft Fabric Mod that adds an Emerald Sword with custom damage. This mod uses the Fabric API and custom damage calculation to enhance the functionality of the Emerald Sword.

