        direction.y = 0;
    } else if (event.key === 'ArrowRight' && direction.x !== -1) {
        direction.x = 1;
        direction.y = 0;
    }
}

function gameLoop() {
    updateSnake();
    drawSnake();
    drawFood();
    drawScore();
    requestAnimationFrame(gameLoop);
}

