const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');
const canvasWidth = canvas.width;
const canvasHeight = canvas.height;

let player = {
    x: canvasWidth / 2,
    y: canvasHeight - 30,
    width: 20,
    height: 20,
    velocity: 0,
    render: function() {
        ctx.fillStyle = 'white';
        ctx.fillRect(this.x, this.y, this.width, this.height);
    },
    jump: function() {
        this.velocity = -10;
        this.render();
    }
};

const pipes = [];
const obstacles = [];
const pipeInterval = 2000;

let lastPipe = 0;
let score = 0;
let highScore = 0;

function spawnPipe() {
    const pipeHeight = Math.floor(Math.random() * 200) + 100;
    const pipe = {
        x: canvasWidth,
        y: Math.floor(Math.random() * (canvasHeight - pipeHeight - 100)),
        width: 50,
        height: pipeHeight,
        render: function() {
            ctx.fillStyle = 'green';
            ctx.fillRect(this.x, this.y, this.width, this.height);
        }
    };
    pipes.push(pipe);

    if (pipe.x < player.x) {
        lastPipe = Date.now();
    }
    if (lastPipe < Date.now() - pipeInterval) {
        obstacles.push({
            x: canvasWidth,
            y: Math.floor(Math.random() * (canvasHeight - 100)),
            width: 50,
            height: 100,
            render: function() {
                ctx.fillStyle = 'green';
                ctx.fillRect(this.x, this.y, this.width, this.height);
            }
        });
    }
}

function drawScore() {
    ctx.fillStyle = 'white';
    ctx.font = '20px Arial';
    ctx.fillText('Score: ' + score, 10, 20);
}

function drawPlayer() {
    player.render();
}

function drawPipes() {
    pipes.forEach(pipe => {
        pipe.render();
    });
}

function drawObstacles() {
    obstacles.forEach(obstacle => {
        obstacle.render();
    });
}

function updatePlayer() {
    player.x += player.velocity;
    if (player.x > canvasWidth) {
        player.x = canvasWidth;
    }
    if (player.x < 0) {
        player.x = 0;
    }
}

function updatePipes() {
    pipes.forEach(pipe => {
        pipe.x -= 5;
        if (pipe.x < -pipe.width) {
            pipes.splice(pipes.indexOf(pipe), 1);
        }
    });
}

function updateObstacles() {
    obstacles.forEach(obstacle => {
        obstacle.x -= 5;
        if (obstacle.x < -obstacle.width) {
            obstacles.splice(obstacles.indexOf(obstacle), 1);
        }
    });
}

function checkCollisions() {
    const playerRect = new howler.Rect(player.x, player.y, player.width, player.height);
    const pipesRect = new howler.Rect(...pipes.map(pipe => ({ x: pipe.x, y: pipe.y, width: pipe.width, height: pipe.height })));
    const obstaclesRect = new howler.Rect(...obstacles.map(obstacle => ({ x: obstacle.x, y: obstacle.y, width: obstacle.width, height: obstacle.height })));
    const collisions = howler.Rect.collide(playerRect, pipesRect) || howler.Rect.collide(playerRect, obstaclesRect);
    if (collisions) {
        score = 0;
        obstacles.length = 0;
        pipes.length = 0;
        player.x = canvasWidth / 2;
        player.y = canvasHeight - 30;
    }
}

function gameLoop() {
    updatePlayer();
    updatePipes();
    updateObstacles();
    checkCollisions();
    drawPlayer();
    drawPipes();
    drawObstacles();
    drawScore();
    requestAnimationFrame(gameLoop);
}

