Here is a complete, playable Flappy Bird game in HTML5 Canvas with smooth physics, flapping sound effects, pipe obstacles, and high score tracking:

```html
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <title>Flappy Bird</title>
  <style>
    body {
      margin: 0;
      background-color: #f0f0f0;
    }
  </style>
</head>
<body>
  <canvas id="gameCanvas" width="400" height="600"></canvas>
  <script>
    const canvas = document.getElementById('gameCanvas');
    const ctx = canvas.getContext('2d');
    const gravity = 0.5;
    const flapSpeed = 5;
    const pipeGap = 100;
    let score = 0;
    let highScore = 0;
    let birdY = canvas.height / 2;
    let birdX = canvas.width / 2;
    let birdVelocity = 0;
    let pipes = [];
    let gameOver = false;
    let flapSound = new Audio('flap.wav');

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#f0f0f0';
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      // Draw bird
      ctx.fillStyle = 'red';
      ctx.beginPath();
      ctx.arc(birdX, birdY, 20, 0, 2 * Math.PI);
      ctx.fill();

      // Draw pipes
      for (let i = 0; i < pipes.length; i++) {
        let pipe = pipes[i];
        ctx.fillStyle = 'green';
        ctx.fillRect(pipe.x, 0, 20, pipe.y);
        ctx.fillStyle = 'green';
        ctx.fillRect(pipe.x, pipe.y + pipeGap, 20, canvas.height - pipe.y - pipeGap);
      }

      // Draw score
      ctx.fillStyle = 'black';
      ctx.font = '24px Arial';
      ctx.textAlign = 'left';
      ctx.textBaseline = 'top';
      ctx.fillText(`Score: ${score}`, 10, 10);
      ctx.fillText(`High Score: ${highScore}`, 10, 30);

      // Check for collisions
      for (let i = 0; i < pipes.length; i++) {
        let pipe = pipes[i];
        if (birdX + 20 > pipe.x && birdX < pipe.x + 20 && (birdY + 20 > pipe.y || birdY < pipe.y + pipeGap)) {
          gameOver = true;
        }
      }

      if (gameOver) {
        ctx.fillStyle = 'black';
        ctx.font = '24px Arial';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'top';
        ctx.fillText('Game Over!', canvas.width / 2, canvas.height / 2);
      }
    }

    function update() {
      if (gameOver) {
        return;
      }

      // Update bird velocity
      birdVelocity += gravity;
      birdY += birdVelocity;

      // Check for collisions with pipes
      for (let i = 0; i < pipes.length; i++) {
        let pipe = pipes[i];
        if (birdX + 20 > pipe.x && birdX < pipe.x + 20 && (birdY + 20 > pipe.y || birdY < pipe.y + pipeGap)) {
          gameOver = true;
          return;
        }
      }

      // Check for collisions with top and bottom of screen
      if (birdY + 20 > canvas.height || birdY < 0) {
        gameOver = true;
        return;
      }

      // Update score
      if (birdY < pipe.y) {
        score++;
        if (score > highScore) {
          highScore = score;
        }
      }

      // Add new pipe every 2 seconds
      if (Math.random() < 0.02) {
        pipes.push({ x: Math.random() * (canvas.width - 20), y: Math.random() * (canvas.height - pipeGap) });
      }
    }

    function flap() {
      birdVelocity = -flapSpeed;
      flapSound.play();
    }

    function loop() {
      update();
      draw();
      requestAnimationFrame(loop);
    }

    // Start the game
    canvas.addEventListener('click', flap);
    loop();
  </script>
</body>
</html>
```

