      ctx.drawImage(background, 0, 0, canvas.width, canvas.height);

      // Draw pipes
      for (let i = 0; i < pipes.length; i++) {
        ctx.drawImage(pipeImage, pipes[i].x, pipes[i].y);
        ctx.drawImage(pipeImage, pipes[i].x, pipes[i].y + 100);
      }

