      for (let i = 0; i < pipes.length; i++) {
        let pipe = pipes[i];
        if (bird.x + bird.width > pipe.x && bird.x < pipe.x + pipeImage.width && (bird.y + bird.height > pipe.y || bird.y < pipe.y + 100)) {
          gameOver = true;
          gameOverSound.play();
          return;
        }
      }

      // Update bird position
      bird.y += bird.velocity;
      bird.velocity += bird.gravity;

      // Check for pipe collision
      for (let i = 0; i < pipes.length; i++) {
        let pipe = pipes[i];
        if (bird.x + bird.width > pipe.x && bird.x < pipe.x + pipeImage.width && (bird.y + bird.height > pipe.y || bird.y < pipe.y + 100)) {
          gameOver = true;
          gameOverSound.play();
          return;
