const canvas = document.getElementById('pongCanvas');
const ctx = canvas.getContext('2d');

const ball = {
  x: canvas.width / 2 - 10,
  y: canvas.height / 2 - 10,
  radius: 10,
  velocityX: 4,
  velocityY: -4
};

const paddleA = {
  x: 30,
  y: canvas.height / 2 - 70,
  width: 10,
  height: 100,
  velocity: 0
};

const paddleB = {
  x: canvas.width - 40,
  y: canvas.height / 2 - 70,
  width: 10,
  height: 100,
  velocity: 0
};

let scoreA = 0;
let scoreB = 0;

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Draw ball
  ctx.beginPath();
  ctx.arc(ball.x, ball.y, ball.radius, 0, Math.PI * 2);
  ctx.fillStyle = 'white';
  ctx.fill();
  ctx.closePath();

  // Draw paddles
  ctx.fillStyle = 'white';
  ctx.fillRect(paddleA.x, paddleA.y, paddleA.width, paddleA.height);
  ctx.fillRect(paddleB.x, paddleB.y, paddleB.width, paddleB.height);

  // Draw score
  ctx.fillStyle = 'white';
  ctx.font = '30px Arial';
  ctx.fillText(`${scoreA}`, 50, 50);
  ctx.fillText(`${scoreB}`, canvas.width - 50, 50);
}

function update() {
  // Update ball position
  ball.x += ball.velocityX;
  ball.y += ball.velocityY;

  // Check for collisions with paddles
  if (ball.x - ball.radius < paddleA.x + paddleA.width && ball.y - ball.radius < paddleA.y + paddleA.height && ball.y + ball.radius > paddleA.y) {
    ball.velocityX = -ball.velocityX;
  }

  if (ball.x + ball.radius > paddleB.x && ball.y - ball.radius < paddleB.y + paddleB.height && ball.y + ball.radius > paddleB.y) {
    ball.velocityX = -ball.velocityX;
  }

  // Check for ball going off the top or bottom
  if (ball.y - ball.radius < 0 || ball.y + ball.radius > canvas.height) {
    ball.velocityY = -ball.velocityY;
  }

  // Check for ball going off the left or right
  if (ball.x - ball.radius < 0) {
    scoreB++;
    resetBall();
  }

  if (ball.x + ball.radius > canvas.width) {
    scoreA++;
    resetBall();
  }
}

function resetBall() {
  ball.x = canvas.width / 2 - 10;
  ball.y = canvas.height / 2 - 10;
  ball.velocityX = -ball.velocityX;
}

function loop() {
  update();
  draw();
  requestAnimationFrame(loop);
}

// Paddle controls
document.addEventListener('keydown', (event) => {
  if (event.key === 'ArrowUp' && paddleA.y > 0) {
    paddleA.y -= 10;
  } else if (event.key === 'ArrowDown' && paddleA.y + paddleA.height < canvas.height) {
    paddleA.y += 10;
  }

  if (event.key === 'w' && paddleB.y > 0) {
    paddleB.y -= 10;
  } else if (event.key === 's' && paddleB.y + paddleB.height < canvas.height) {
    paddleB.y += 10;
  }
});

loop();
