```javascript
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');
const canvasWidth = canvas.width = 280;
const canvasHeight = canvas.height = 500;

const player = {
  x: 10,
  y: canvasHeight / 2,
  width: 20,
  height: 20,
  velocity: 0,
  score: 0,
  isAlive: true
};

const pipes = [];
const pipeInterval = 2000; // Time in milliseconds between new pipes

let flapped = false;

function drawPlayer() {
  ctx.fillStyle = '#ff0000';
  ctx.fillRect(player.x, player.y, player.width, player.height);
}

function drawPipes() {
  pipes.forEach(pipe => {
    ctx.fillStyle = '#00ff00';
    ctx.fillRect(pipe.x, pipe.y, pipe.width, pipe.height);

    ctx.fillStyle = '#000000';
    ctx.fillRect(pipe.x + pipe.width, pipe.y, 10, pipe.height);
  });
}

function updatePlayer() {
  player.velocity = 0;
  if (flapped) {
    player.velocity = -10;
    flapped = false;
  }
  player.y += player.velocity;

  if (player.y < 0) {
    player.y = 0;
  } else if (player.y + player.height > canvasHeight) {
    player.isAlive = false;
  }
}

function updatePipes() {
  pipes.forEach((pipe, index) => {
    pipe.x -= 5;

    if (pipe.x + pipe.width < 0) {
      pipes.splice(index, 1);
    }
  });

  if (!player.isAlive) {
    setTimeout(() => {
      player.isAlive = true;
      player.score = 0;
      pipes = [];
    }, 1000);
  }
}

function createPipes() {
  const gap = 100;
  const pipeHeight = 50;
  const pipeWidth = 50;
  const gapHeight = canvasHeight - pipeHeight - gap;

  const topPipe = {
    x: canvasWidth,
    y: gapHeight,
    width: pipeWidth,
    height: pipeHeight
  };

  const bottomPipe = {
    x: canvasWidth,
    y: gapHeight + gap,
    width: pipeWidth,
    height: pipeHeight
  };

  pipes.push(topPipe);
  pipes.push(bottomPipe);
}

function checkCollisions() {
  if (player.isAlive) {
    pipes.forEach(pipe => {
      if (pipe.x < player.x + player.width && pipe.x + pipe.width > player.x &&
          (pipe.y < player.y + player.height || pipe.y + pipe.height > player.y)) {
        player.isAlive = false;
        return;
      }
    });
  }
}

function drawScore() {
  ctx.fillStyle = '#ff0000';
  ctx.font = '20px Arial';
  ctx.fillText(`Score: ${player.score}`, 10, 30);
}

function loop() {
  ctx.clearRect(0, 0, canvasWidth, canvasHeight);
  drawPlayer();
  drawPipes();
  updatePlayer();
  updatePipes();
  checkCollisions();
  drawScore();

  if (player.isAlive) {
    requestAnimationFrame(loop);
  } else {
    alert(`Game Over! Your score: ${player.score}`);
  }
}

function flappyKeyPressed(event) {
  if (event.key === 'Space' || event.key === ' ') {
    if (!flapped) {
      flapped = true;
      player.velocity = 10;
    }
  }
}

function flappyKeyUp() {
  flapped = false;
}

document.addEventListener('keydown', flappyKeyPressed);
document.addEventListener('keyup', flappyKeyUp);

createPipes();
loop();
