  ['R', '#ff0000'],
  ['B', '#0000ff'],
  ['Y', '#ffff00'],
  ['C', '#00ffff'],
  ['M', '#ff00ff'],
  ['K', '#000000'],
  ['W', '#ffffff'],
]);

const blocks = [
