  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, canvasWidth, canvasHeight);
  ctx.fillStyle = '#fff';
  ctx.strokeStyle = '#000';
  ctx.lineWidth = 2;

  for (let y = 0; y < gridHeight; y++) {
    for (let x = 0; x < gridWidth; x++) {
      const color = grid[y][x] ? blockColors[grid[y][x] - 1] : '#000000';
      ctx.fillStyle = color;
      ctx.fillRect(x * gridSize, y * gridSize, gridSize, gridSize);
      ctx.strokeStyle = color;
      ctx.strokeRect(x * gridSize, y * gridSize, gridSize, gridSize);
    }
  }
}

function drawCurrentBlock() {
  for (let y = 0; y < currentBlock.length; y++) {
    for (let x = 0; x < currentBlock[y].length; x++) {
      if (currentBlock[y][x] === 1) {
        ctx.fillStyle = currentBlockColors[currentBlock[y][x]];
        ctx.fillRect((currentBlockX + x) * gridSize, (currentBlockY + y) * gridSize, gridSize, gridSize);
