  }
}

function checkLines() {
  for (let y = gridHeight - 1; y >= 0; y--) {
    let fullLine = true;
    for (let x = 0; x < gridWidth; x++) {
      if (grid[y][x] === 0) {
        fullLine = false;
        break;
      }
    }
    if (fullLine) {
      for (let x = 0; x < gridWidth; x++) {
        grid[y][x] = grid[y + 1][x];
      }
      grid[y + 1].fill(0);
      score += 10;
    }
  }
}

function startGame() {
  currentBlock = blocks[0];
  currentBlockX = 3;
  currentBlockY = 0;
  score = 0;
  drawGrid();
  drawCurrentBlock();
}

startGame();

function loop() {
  requestAnimationFrame(loop);
  moveBlockDownAndCheckCollision();
}

document.addEventListener('keydown', (event) => {
  if (event.key === 'ArrowLeft') {
    moveBlockLeft();
  } else if (event.key === 'ArrowRight') {
    moveBlockRight();
  } else if (event.key === 'ArrowDown') {
    moveBlockDown();
  } else if (event.key === ' ' || event.key === 'Enter') {
    moveBlockDownAndCheckCollision();
  }
});

loop();
```

### Explanation

- **Grid and Blocks**: The grid is represented as a 2D array where each cell can be one of the block colors.
- **Blocks**: The blocks are represented as arrays of arrays, where each inner array represents a row of the block.
- **Drawing**: The grid and current block are drawn using the canvas context.
- **Collision Detection**: The game checks for collisions with the grid and the bottom of the screen.
- **Movement and Rotation**: The current block can be moved left, right, and down, and it can be rotated.
- **Score**: The score is incremented when lines are cleared.
- **Game Loop**: The game loop is set up to continuously check for new blocks and handle key presses.

